from solution import choose_num
import pytest
from hypothesis import given
import hypothesis.strategies as st


# --- Explicit examples from spec docstring ---

def test_example_12_15_returns_14():
    assert choose_num(12, 15) == 14


def test_example_13_12_returns_minus_one():
    assert choose_num(13, 12) == -1


# --- Single-value / boundary examples derived from spec ---

def test_single_value_even_returns_itself():
    assert choose_num(2, 2) == 2
    assert choose_num(4, 4) == 4
    assert choose_num(12, 12) == 12


def test_single_value_odd_returns_minus_one():
    assert choose_num(1, 1) == -1
    assert choose_num(3, 3) == -1
    assert choose_num(13, 13) == -1
    assert choose_num(15, 15) == -1


def test_single_value_multiple_of_three_odd_returns_minus_one():
    # Guards against confusing divisibility by 3 with evenness.
    assert choose_num(3, 3) == -1
    assert choose_num(9, 9) == -1
    assert choose_num(15, 15) == -1
    assert choose_num(21, 21) == -1


def test_single_value_multiple_of_three_even_returns_itself():
    assert choose_num(6, 6) == 6
    assert choose_num(12, 12) == 12


def test_range_with_no_even_returns_minus_one():
    assert choose_num(1, 1) == -1
    assert choose_num(13, 13) == -1
    assert choose_num(11, 11) == -1


def test_x_greater_than_y_returns_minus_one():
    assert choose_num(13, 12) == -1
    assert choose_num(2, 1) == -1
    assert choose_num(15, 12) == -1
    assert choose_num(5, 4) == -1


def test_touching_intervals():
    # [x, y] inclusive with y = x + 1 always contains exactly one even.
    assert choose_num(1, 2) == 2
    assert choose_num(2, 3) == 2
    assert choose_num(13, 14) == 14
    assert choose_num(14, 15) == 14


def test_biggest_even_not_smallest():
    assert choose_num(12, 15) == 14
    assert choose_num(10, 20) == 20
    assert choose_num(10, 19) == 18
    assert choose_num(11, 19) == 18
    assert choose_num(11, 20) == 20


# --- Property-based tests against reference model ---

def _reference(x, y):
    if x > y:
        return -1
    for n in range(y, x - 1, -1):
        if n % 2 == 0:
            return n
    return -1


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_matches_reference_model(x, y):
    assert choose_num(x, y) == _reference(x, y)


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_result_is_in_range_and_even_or_minus_one(x, y):
    r = choose_num(x, y)
    if r == -1:
        # -1 is only allowed sentinel; it must not be confused with a valid answer
        assert True
    else:
        assert r % 2 == 0
        assert x <= r <= y


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_result_is_maximal_even_in_range(x, y):
    r = choose_num(x, y)
    if x <= y:
        evens = [n for n in range(x, y + 1) if n % 2 == 0]
        if evens:
            assert r == max(evens)
        else:
            assert r == -1
    else:
        assert r == -1


@given(st.integers(min_value=1, max_value=500))
def test_minus_one_iff_no_even_in_range(y):
    # For x <= y: result == -1 iff interval contains no even number.
    for x in (1, y, max(1, y - 1), max(1, y - 2)):
        if x <= y:
            r = choose_num(x, y)
            has_even = any(n % 2 == 0 for n in range(x, y + 1))
            assert (r == -1) == (not has_even)


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_no_larger_even_fits(x, y):
    r = choose_num(x, y)
    if r != -1:
        # There must be no even number strictly between r and y inclusive of y.
        assert r + 2 > y
    else:
        if x <= y:
            assert all(n % 2 == 1 for n in range(x, y + 1))
        else:
            assert True


@given(st.integers(min_value=1, max_value=998))
def test_parity_of_upper_bound_determines_answer_when_interval_wide(x):
    # If interval has at least 2 numbers, answer is forced by y's parity.
    y = x + 2
    r = choose_num(x, y)
    assert r % 2 == 0
    assert r == (y if y % 2 == 0 else y - 1)


@given(st.integers(min_value=2, max_value=1000))
def test_singleton_matches_parity(y):
    r = choose_num(y, y)
    assert r == (y if y % 2 == 0 else -1)
